// อ่าน invite จาก URL hash + apply config
const consumeInvite = () => {
  if (typeof location === 'undefined') return false;
  const m = location.hash.match(/[#&]join=([A-Za-z0-9_-]+)/);
  if (!m) return false;
  const payload = decodeInvite(m[1]);
  if (!payload || !payload.bucket) return false;
  // apply config
  if (payload.fb) setFirebaseUrl(payload.fb);
  if (payload.jbk) setApiKey('jsonbin', payload.jbk);
  const newCfg = {
    enabled: true,
    bucketUrl: payload.bucket,
    deviceId: 'dev-' + Math.random().toString(36).slice(2, 8),
    lastPushAt: 0, lastPullAt: 0, lastVersion: 0
  };
  setSyncConfig(newCfg);
  // เอา hash ออก เพื่อกัน apply ซ้ำ
  try { history.replaceState(null, '', location.pathname + location.search); } catch (e) {}
  return true;
};
