// สร้าง bucket ใหม่ — Firebase (ถ้ามี URL) → JSONBin → jsonblob → npoint
const createSyncBucket = async () => {
  const errors = [];

  // 0) Firebase — ถ้าผู้ใช้ตั้ง Firebase URL ไว้ → สร้างห้องใต้ path /rooms/<random>
  const fbUrl = getFirebaseUrl();
  if (fbUrl) {
    try {
      const base = fbUrl.replace(/\/+$/, '');
      const roomId = 'room-' + Math.random().toString(36).slice(2, 10);
      const url = `${base}/flowdesk/${roomId}.json`;
      const initial = { _created: Date.now(), data: {} };
      const res = await fetch(url, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(initial)
      });
      if (res.ok) return url;
      const txt = await res.text().catch(() => '');
      errors.push(`firebase: HTTP ${res.status}${txt ? ' (' + txt.slice(0, 80) + ')' : ''}`);
    } catch (e) { errors.push('firebase: ' + e.message); }
  } else {
    errors.push('firebase: ยังไม่ได้ใส่ Firebase URL');
  }

  // 1) JSONBin.io พร้อม API key ของผู้ใช้ — เสถียรอันดับ 2
  const apiKey = getApiKey('jsonbin');
  if (apiKey) {
    try {
      const initial = { _created: Date.now(), data: {} };
      const res = await fetch('https://api.jsonbin.io/v3/b', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-Master-Key': apiKey,
          'X-Bin-Name': 'flowdesk-sync-' + Date.now()
        },
        body: JSON.stringify(initial)
      });
      if (res.ok) {
        const data = await res.json();
        const id = data?.metadata?.id;
        if (id) return `https://api.jsonbin.io/v3/b/${id}/latest`;
        errors.push('jsonbin: response ไม่มี id');
      } else {
        const txt = await res.text().catch(() => '');
        errors.push(`jsonbin: HTTP ${res.status}${txt ? ' (' + txt.slice(0, 80) + ')' : ''}`);
      }
    } catch (e) { errors.push('jsonbin: ' + e.message); }
  } else {
    errors.push('jsonbin: ยังไม่ได้ใส่ API key');
  }

  // 2) ลอง jsonblob.com — CORS allow *, ไม่ต้อง signup
  try {
    const initial = { _created: Date.now(), data: {} };
    const res = await fetch('https://jsonblob.com/api/jsonBlob', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
      body: JSON.stringify(initial)
    });
    if (res.ok || res.status === 201) {
      const loc = res.headers.get('Location') || res.headers.get('Content-Location') || res.headers.get('X-jsonblob');
      if (loc) {
        const url = loc.startsWith('http') ? loc : `https://jsonblob.com${loc}`;
        return url;
      }
      errors.push('jsonblob: ตอบกลับแต่ไม่มี Location header');
    } else {
      errors.push(`jsonblob: HTTP ${res.status}`);
    }
  } catch (e) { errors.push('jsonblob: ' + e.message); }

  // 3) Fallback npoint.io — anonymous, ใช้ POST root
  try {
    const initial = { _created: Date.now(), data: {} };
    const res = await fetch('https://api.npoint.io/', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(initial)
    });
    if (res.ok) {
      const data = await res.json();
      if (data && data.id) return `https://api.npoint.io/${data.id}`;
      errors.push('npoint: response ไม่มี id');
    } else {
      errors.push(`npoint: HTTP ${res.status}`);
    }
  } catch (e) { errors.push('npoint: ' + e.message); }

  // ทุก provider fail
  const isFile = (typeof location !== 'undefined' && location.protocol === 'file:');
  const hint = isFile
    ? ' · คุณเปิดไฟล์จาก file:// — browser block CORS · แนะนำอัพไฟล์ขึ้น tiiny.host หรือ Netlify (drag-drop ฟรี) แล้วลองใหม่ · หรือใช้ "ส่งออก/นำเข้า JSON" ใน tab ทั่วไป'
    : ' · เน็ตอาจมีปัญหา หรือ providers ล่ม';
  throw new Error('สร้างห้องไม่สำเร็จ' + hint + ' · รายละเอียด: ' + errors.join(' | '));
};

// ===== Merge helpers — กัน last-write-wins ทำให้ข้อมูลข้ามเครื่องหาย =====
// ใช้ตอน pull: รวม cloud + local แทนการ overwrite
// (parseThDT นิยามใน block แรก — ใช้ผ่าน window)
const _stepScore = (r) => (r.flow || []).filter(s => s.status === 'approved' || s.status === 'rejected').length;
const _reqRecency = (r) => {
  // คะแนนความใหม่ — สูง = ใหม่กว่า
  let s = _stepScore(r) * 1000;
  if (r.completedAt) s += 500;
  if (r.receivedAt) s += 200;
  if (r.cleared) s += 100;
  if (r.clearingStatus === 'submitted') s += 150;
  if (r.clearingStatus === 'verified' || r.clearingStatus === 'rejected') s += 300;
  if (r.status === 'revision') s += 150;
  if (r.flow && r.flow.length) {
    // หา timestamp ล่าสุดใน flow — 🐛FIX: ใช้ parseThDT (Date.parse อ่าน DD/MM ไทยผิด/NaN)
    const ats = r.flow.map(x => x.at).filter(Boolean).map(a => parseThDT(a)?.getTime()).filter(n => n && !isNaN(n));
    if (ats.length) s += Math.floor((Math.max(...ats) - 1700000000000) / 60000); // นาทีตั้งแต่ ref
  }
  return s;
};
const mergeRequests = (local, remote) => {
  if (!Array.isArray(local)) local = [];
  if (!Array.isArray(remote)) remote = [];
  const byId = new Map();
  local.forEach(r => { if (r && r.id) byId.set(r.id, r); });
  remote.forEach(r => {
    if (!r || !r.id) return;
    const existing = byId.get(r.id);
    if (!existing) { byId.set(r.id, r); return; }
    // 🐛FIX: ใช้ updatedAt เป็นเกณฑ์หลัก (ครอบคลุม comment/priority/verify ที่ recency มองไม่เห็น)
    const ur = r.updatedAt || 0, ue = existing.updatedAt || 0;
    if (ur !== ue) { byId.set(r.id, ur > ue ? r : existing); return; }
    // ไม่มี updatedAt ทั้งคู่/เท่ากัน — fallback recency (cloud เสมอกัน → trust cloud)
    byId.set(r.id, _reqRecency(r) >= _reqRecency(existing) ? r : existing);
  });
  return Array.from(byId.values()).sort((a, b) => (b.id || '').localeCompare(a.id || ''));
};
const mergeActivities = (local, remote) => {
  if (!Array.isArray(local)) local = [];
  if (!Array.isArray(remote)) remote = [];
  const key = (a) => `${a.at || ''}|${a.user || ''}|${a.action || ''}|${a.refId || ''}|${a.summary || ''}`;
  const seen = new Set();
  const result = [];
  [...remote, ...local].forEach(a => {
    if (!a) return;
    const k = key(a);
    if (!seen.has(k)) { seen.add(k); result.push(a); }
  });
  // 🐛FIX: sort ใหม่→เก่า ก่อนตัด 500 — เดิม remote มาก่อนเสมอ ทำ audit log เรียงผิด
  // และรายการใหม่ล่าสุดของเครื่องนี้โดนตัดทิ้งก่อน
  result.sort((a, b) => (parseThDT(b.at)?.getTime() || 0) - (parseThDT(a.at)?.getTime() || 0));
  return result.slice(0, 500);
};
const mergeUsersById = (local, remote) => {
  // users เป็น object — รวม keys · 🐛FIX: เทียบ updatedAt แทน remote-ทับ-เสมอ
  // (เดิม: ตั้งรหัสผ่าน/แก้ user บนเครื่อง A โดน cloud copy เก่าทับกลับ)
  const out = { ...(local || {}) };
  Object.entries(remote || {}).forEach(([k, v]) => {
    if (!v) return;
    const loc = out[k];
    if (!loc) { out[k] = v; return; }
    out[k] = (v.updatedAt || 0) >= (loc.updatedAt || 0) ? v : loc;
  });
  return out;
};
const mergeArrayByKey = (local, remote, keyField) => {
  if (!Array.isArray(local)) local = [];
  if (!Array.isArray(remote)) remote = [];
  const byKey = new Map();
  local.forEach(x => { if (x && x[keyField]) byKey.set(x[keyField], x); });
  remote.forEach(x => { if (x && x[keyField]) byKey.set(x[keyField], x); });
  return Array.from(byKey.values());
};

// ดึงข้อมูลล่าสุดจาก cloud
const pullFromCloud = async (bucketUrl) => {
  if (!bucketUrl) return null;
  const provider = detectProvider(bucketUrl);
  try {
    const headers = {};
    if (provider === 'jsonbin') {
      headers['X-Bin-Meta'] = 'false';
      const k = getApiKey('jsonbin'); if (k) headers['X-Master-Key'] = k;
    }
    const res = await fetch(bucketUrl, { method: 'GET', headers });
    if (res.status === 404) return null;
    if (!res.ok) throw new Error('Pull HTTP ' + res.status);
    const text = await res.text();
    if (!text || text.trim() === '' || text === 'null') return null;
    const parsed = JSON.parse(text);
    // Firebase / npoint / jsonblob: { _created, data }
    // jsonbin (X-Bin-Meta:false): { _created, data } | else: { record: {...} }
    const root = (parsed && parsed.record) ? parsed.record : parsed;
    return root && root.data ? root.data : root;
  } catch (e) {
    console.warn('Cloud pull failed:', e.message);
    return null;
  }
};

// ส่งข้อมูลขึ้น cloud (overwrite)
const pushToCloud = async (bucketUrl, payload) => {
  if (!bucketUrl) return false;
  const provider = detectProvider(bucketUrl);
  try {
    // method per provider: firebase=PUT, jsonblob=PUT, jsonbin=PUT, npoint=POST
    const method = provider === 'npoint' ? 'POST' : 'PUT';
    let url = bucketUrl;
    if (provider === 'jsonbin' && url.endsWith('/latest')) url = url.replace(/\/latest$/, '');
    const headers = { 'Content-Type': 'application/json' };
    if (provider === 'jsonbin') {
      headers['X-Bin-Versioning'] = 'false';
      const k = getApiKey('jsonbin'); if (k) headers['X-Master-Key'] = k;
    }
    const body = JSON.stringify({ _created: Date.now(), data: payload });
    const res = await fetch(url, { method, headers, body });
    if (!res.ok) throw new Error('Push HTTP ' + res.status);
    return true;
  } catch (e) {
    console.warn('Cloud push failed:', e.message);
    return false;
  }
};

